func TestTraceparent(t *testing.T) {
	const header = "00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01"
	sc, ok := ParseTraceparent(header)
	if !ok || !sc.Sampled || sc.Traceparent() != header {
		t.Fatalf("ParseTraceparent(%q) = %+v %v", header, sc, ok)
	}
	for _, bad := range []string{
		"",
		"00-00000000000000000000000000000000-00f067aa0ba902b7-01",
		"00-4bf92f3577b34da6a3ce929d0e0e4736-0000000000000000-01",
		"00-4BF92F3577B34DA6A3CE929D0E0E4736-00f067aa0ba902b7-01",
		"ff-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01",
		"00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01-extra",
		"00-4bf92f3577b34da6a3ce929d0e0e473-00f067aa0ba902b7-01",
	} {
		if _, ok := ParseTraceparent(bad); ok {
			t.Errorf("ParseTraceparent(%q) accepted an invalid header", bad)
		}
	}
	if _, ok := ParseTraceparent("cc-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01-future"); !ok {
		t.Error("a future version with extra fields was rejected")
	}
	if Tracestate([]string{"a=1", "b=2"}) != "a=1,b=2" || Tracestate([]string{strings.Repeat("x", maxTracestate+1)}) != "" {
		t.Error("tracestate is not joined and bounded")
	}
}

