func TestLoadConfig(t *testing.T) {
	env := map[string]string{
		"OTEL_EXPORTER_OTLP_ENDPOINT": "http://collector:4318/",
		"OTEL_EXPORTER_OTLP_HEADERS":  "authorization=Bearer%20abc, x-team = core",
		"OTEL_TRACES_SAMPLER":         "parentbased_traceidratio",
		"OTEL_TRACES_SAMPLER_ARG":     "0.25",
		"METRICS_ADDR":                ":9090",
	}
	cfg, err := LoadConfig(func(k string) string { return env[k] }, "api")
	if err != nil {
		t.Fatal(err)
	}
	if cfg.ServiceName != "api" || cfg.TracesEndpoint != "http://collector:4318/v1/traces" || cfg.MetricsAddr != ":9090" {
		t.Fatalf("config = %+v", cfg)
	}
	if cfg.TracesHeaders.Get("Authorization") != "Bearer abc" || cfg.TracesHeaders.Get("X-Team") != "core" {
		t.Fatalf("headers = %v", cfg.TracesHeaders)
	}
	if !cfg.Sampler.ParentBased || cfg.Sampler.Ratio != 0.25 {
		t.Fatalf("sampler = %+v", cfg.Sampler)
	}
	env["OTEL_SDK_DISABLED"] = "true"
	if cfg, _ := LoadConfig(func(k string) string { return env[k] }, "api"); cfg.TracesEndpoint != "" {
		t.Fatal("OTEL_SDK_DISABLED did not disable tracing")
	}
	bad := map[string]string{
		"OTEL_EXPORTER_OTLP_ENDPOINT": "collector:4318",
		"OTEL_EXPORTER_OTLP_PROTOCOL": "grpc",
		"OTEL_EXPORTER_OTLP_HEADERS":  "novalue",
		"OTEL_TRACES_SAMPLER":         "sometimes",
		"OTEL_TRACES_SAMPLER_ARG":     "2",
	}
	_, err = LoadConfig(func(k string) string { return bad[k] }, "api")
	for key := range bad {
		if err == nil || !strings.Contains(err.Error(), key) {
			t.Errorf("invalid %s was not reported: %v", key, err)
		}
	}
}

func TestSampler(t *testing.T) {
	var traceID [16]byte
	traceID[8] = 0x10
	parent := SpanContext{Sampled: false}
	tests := []struct {
		sampler   Sampler
		hasParent bool
		want      bool
	}{
		{sampler: Sampler{ParentBased: true, Ratio: 1}, hasParent: true, want: false},
		{sampler: Sampler{ParentBased: true, Ratio: 1}, want: true},
		{sampler: Sampler{Ratio: 0}, want: false},
		{sampler: Sampler{Ratio: 0.5}, want: true},
		{sampler: Sampler{Ratio: 0.01}, want: false},
	}
	for _, tt := range tests {
		if got := tt.sampler.sample(parent, tt.hasParent, traceID); got != tt.want {
			t.Errorf("%+v with parent %v = %v", tt.sampler, tt.hasParent, got)
		}
	}
}

